    const cards = rows.map((r) => '<li><a href="/ilan/' + encodeURIComponent(r.id) + "/" + citySlug(r.title).slice(0, 80).replace(/-+$/, "") + '/">' + esc(r.title) + "</a><small>" + esc([r.district, r.city].filter(Boolean).join(" / ")) + "</small></li>").join("");
