function cookieToken(request) {
  const raw = request.headers.get("Cookie") || "";
  const x = raw.split(";").map((s) => s.trim()).find((s) => s.startsWith(MEMBER_COOKIE + "="));
  try {
    return x ? decodeURIComponent(x.slice(MEMBER_COOKIE.length + 1)) : "";
  } catch {
    return "";
  }
}
async function currentMember(request, env) {
  const token = cookieToken(request);
  if (!token || !env.DB) return null;
  return await env.DB.prepare("SELECT u.id,u.email,u.role FROM user_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>? AND u.active=1 AND u.role='member'").bind(await digest(token), Math.floor(Date.now() / 1e3)).first();
}
async function requireMember(context) {
  if (!isAllowedOrigin(context.request) && !["GET", "HEAD"].includes(context.request.method)) return { response: fail("\u0130stek kayna\u011F\u0131 do\u011Frulanamad\u0131.", 403) };
  if (!context.env.DB) return { response: fail("D1 ba\u011Flant\u0131s\u0131 hen\xFCz yap\u0131lmam\u0131\u015F.", 503) };
  const member = await currentMember(context.request, context.env);
  return member ? { member } : { response: fail("\u0130lan vermek i\xE7in \xF6nce hesab\u0131na giri\u015F yap.", 401) };
}
async function verifyTurnstile(token, request, env) {
  if (!env.TURNSTILE_SECRET || !env.TURNSTILE_SITE_KEY) return false;
  if (typeof token !== "string" || token.length < 10 || token.length > 2048) return false;
  try {
    const res = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", { method: "POST", signal: AbortSignal.timeout(1e4), headers: { "content-type": "application/x-www-form-urlencoded" }, body: (() => {
      const v = new URLSearchParams({ secret: env.TURNSTILE_SECRET, response: token }), ip = request.headers.get("CF-Connecting-IP");
      if (ip) v.set("remoteip", ip);
      return v;
    })() });
    if (!res.ok) return false;
    const data = await res.json();
    return data.success === true && data.action === "member_auth" && ["yukvinc.com.tr", "www.yukvinc.com.tr"].includes(data.hostname);
  } catch {
    return false;
  }
}
async function limited(env, request, action, max = 8, windowSecs = 3600) {
  const h = await ipHash(request), now = Math.floor(Date.now() / 1e3);
  await env.DB.prepare("DELETE FROM user_login_attempts WHERE created_at<?").bind(now - 86400).run();
  const r = await env.DB.prepare("SELECT COUNT(*) n FROM user_login_attempts WHERE ip_hash=? AND action=? AND created_at>?").bind(h, action, now - windowSecs).first();
  if (Number(r?.n || 0) >= max) return true;
  await env.DB.prepare("INSERT INTO user_login_attempts(ip_hash,action) VALUES(?,?)").bind(h, action).run();
  return false;
}
async function clearAttempts(env, request, action) {
  await env.DB.prepare("DELETE FROM user_login_attempts WHERE ip_hash=? AND action=?").bind(await ipHash(request), action).run();
}
async function createSession(env, userId) {
  const token = randomId(32), hash2 = await digest(token), now = Math.floor(Date.now() / 1e3);
  await env.DB.prepare("DELETE FROM user_sessions WHERE expires_at<=?").bind(now).run();
  await env.DB.prepare("INSERT INTO user_sessions(token_hash,user_id,expires_at) VALUES(?,?,?)").bind(hash2, userId, now + MEMBER_SECONDS).run();
  return token;
}
async function readMemberJson(request, max = 2e4) {
  const type = (request.headers.get("content-type") || "").toLowerCase();
  try {
    if (type.includes("application/json")) return await readJson(request, max);
    if (type.includes("application/x-www-form-urlencoded")) {
      const raw = await readBoundedText(request, max);
      const params = new URLSearchParams(raw), data = {};
      for (const [key, value] of params) {
        if (Object.prototype.hasOwnProperty.call(data, key)) throw new Error("Tekrarlanan alan.");
        data[key] = value;
      }
      return data;
    }
    throw new Error("Desteklenmeyen form t\xFCr\xFC.");
  } catch (e) {
    if (String(e?.message || "").includes("\u0130stek \xE7ok b\xFCy\xFCk")) throw new Error("\u0130stek \xE7ok b\xFCy\xFCk.");
    throw new Error("Form verileri okunamad\u0131.");
  }
}
async function createMember(env, email, password) {
  const id2 = randomId(16), encoded = await hashPassword(password);
  await env.DB.prepare("INSERT INTO users(id,email,email_norm,password_hash,role,active) VALUES(?,?,?,?,'member',1)").bind(id2, email, email, encoded).run();
  return { id: id2, email, role: "member" };
}
async function loginMember(env, email, password) {
  const user = await env.DB.prepare("SELECT id,email,password_hash,role,active FROM users WHERE email_norm=? AND role='member'").bind(email).first();
  const dummy = "pbkdf2$100000$MDEyMzQ1Njc4OWFiY2RlZg$4iB6f3p-jfQ5csC8mIi0oGZleGrJ2z1Tl3taRaVsmxM";
  const ok = await verifyPassword(password, user?.password_hash || dummy);
  return user && Number(user.active) === 1 && ok ? { id: user.id, email: user.email, role: user.role } : null;
}

