var BAD_SALE = /\b((?:vinc|manlift|manito|manitou|telehandler|platform)\s+(?:satilik|satisi|satin alma|satin alinmasi|mal alimi)|satilik\s+(?:vinc|manlift|manito|manitou|telehandler|platform)|koprulu gezer vinc alimi|raf sistemi|ikinci el vinc satis|gayrimenkul kiralama)\b/;
