    return json2({ job: { id: job.id, title: job.title, city: job.city, district: job.district, status: job.status, selected_offer_id: job.selected_offer_id }, offers: (rows.results || []).map((x) => ({ ...x, company: x.company_name || x.display_name || "Makine sahibi" })) });
