    if (!Number.isInteger(price) || price < 100 || price > 1e8 || !arrival || arrival.length > 100 || message.length > 400 || hasPublicContact(message + " " + arrival) || !["KDV dahil", "KDV hari\xE7"].includes(d.vat) || !["Ula\u015F\u0131m dahil", "Ula\u015F\u0131m ayr\u0131ca"].includes(d.travel)) return json2({ error: "Fiyat, geli\u015F zaman\u0131 ve teklif bilgilerini kontrol et. \u0130leti\u015Fim bilgisi yazma." }, 400);
    const key = uid(), r = await env.DB.prepare("INSERT INTO job_offers(id,job_id,bidder_id,listing_id,price,arrival,vat,travel,message) SELECT ?,?,?,?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM job_requests WHERE id=? AND status='open' AND user_id<>?) AND EXISTS(SELECT 1 FROM listings l WHERE l.id=? AND " + eligibleSql + ") ON CONFLICT(job_id,bidder_id) DO UPDATE SET listing_id=excluded.listing_id,price=excluded.price,arrival=excluded.arrival,vat=excluded.vat,travel=excluded.travel,message=excluded.message,updated_at=unixepoch() WHERE job_offers.status='submitted'").bind(key, id2, member.id, String(d.listing_id || ""), price, arrival, d.vat, d.travel, message, id2, member.id, String(d.listing_id || ""), member.id).run();
