        const direct = items.results || [];
        const firstCard = (label, heading, body, direct=false) => '<article class="job-card'+(direct?' job-direct':'')+'"><div class="job-icon" aria-hidden="true">▤</div><div>'+(direct?'<span class="direct-source">Doğrudan iş talebi</span>':'')+'<div class="job-category">'+esc4(label)+'</div><h3>'+heading+'</h3>'+body+'</div></article>';
