function nationalSourceCatalog(code) {
  const province = PROVINCES.find((p) => p.id === Number(code));
  if (!province) return null;
  const items = catalog.filter((x) => Number(x.code) === Number(code));
  return { province: province.name, districtCount: province.districts.length, districts: province.districts.map((x) => x.name), total: items.length, items, automaticSources: false, source: "https://www.tbb.gov.tr/tr/buyuksehir-ve-il-belediyeleri" };
}
function nationalCoverage() {
  return { provinces: PROVINCES.length, districts: PROVINCES.reduce((n, p) => n + p.districts.length, 0), municipalities: catalog.length };
}
function nationalDemandQueries(code, district = "", neighborhood = "") {
  const province = PROVINCES.find((p) => p.id === Number(code));
  if (!province) return null;
  if (district && !province.districts.some((x) => x.name === district)) return null;
  const clean = String(neighborhood).trim().replace(/\s+/g, " ");
  if (clean.length > 100 || /[<>"\\\u0000-\u001f\u007f]/.test(String(neighborhood))) return null;
  const locationTerms = [province.name, district, clean].filter(Boolean);
  const location = locationTerms.map((value) => '"' + value + '"').join(" ");
  const groups = [
    ["Vin\xE7", "crane", '("vin\xE7 aran\u0131yor" OR "vin\xE7 laz\u0131m" OR "vin\xE7 kiralamak istiyorum" OR "vin\xE7 kiralamak istiyoruz" OR "vin\xE7 kiralama talebi" OR "vin\xE7 hizmet al\u0131m\u0131" OR "ayl\u0131k vin\xE7 aran\u0131yor" OR "uzun d\xF6nem vin\xE7 kiralama talebi")'],
    ["Manlift", "manlift", '("manlift aran\u0131yor" OR "manlift laz\u0131m" OR "manlift kiralamak istiyorum" OR "manlift kiralamak istiyoruz" OR "manlift kiralama talebi" OR "platform kiralanacakt\u0131r" OR "ayl\u0131k manlift aran\u0131yor")'],
    ["Manito / telehandler", "telehandler", '("manito kiralamak istiyorum" OR "manito kiralamak istiyoruz" OR "manito aran\u0131yor" OR "manitou kiralama talebi" OR "telehandler aran\u0131yor" OR "teleskopik forklift kiralanacakt\u0131r" OR "ayl\u0131k manito aran\u0131yor" OR "uzun d\xF6nem telehandler talebi")'],
    ["Montaj / makine indirme", "industrial_lifting", '("makine indirme" OR "fabrika makine montaj\u0131" OR "pres makinesi yerle\u015Ftirme") ("teklif istiyoruz" OR "teklif isteniyor" OR "vin\xE7 laz\u0131m" OR "hizmet al\u0131m\u0131")']
  ];
  const exclusions = ' -"sat\u0131l\u0131k" -"operat\xF6r\xFC aran\u0131yor" -"filomuz" -"kiraya veriyoruz"';
  return {
    province: province.name,
    district,
    neighborhood: clean,
    locationTerms,
    automaticExecution: false,
    sourcePublishedAtRequired: true,
    freshness: { searchFilter: "past_24_hours", parameter: "tbs=qdr:d", indexFilterOnly: true, provesSourcePublicationTime: false },
    queries: groups.map(([label, equipment, terms]) => {
      const query = location + " " + terms + exclusions;
      const url = new URL("https://www.google.com/search");
      url.searchParams.set("q", query);
      url.searchParams.set("tbs", "qdr:d");
      return {
        label,
        equipment,
        intent: "rental_buyer",
        query,
        url: url.href,
        sourcePublishedAtRequired: true,
        automaticPublication: false
      };
    })
  };
}

