scanPermittedHtmlSource = async function (baseUrl, options = {}) {
  const result = await __yvV197BaseHtmlScan(baseUrl, options);
  if (!result || !Array.isArray(result.items) || !result.items.length) return result;
  const base = new URL(baseUrl);
  let checked = 0, enriched = 0;
  const equip = /vinc|sepetli|manlift|platform|hiyap|hiab|is makine|makine kirala|ekskavator|forklift|kaldirma|lowbed|nakliye/;
  const demand = /kirala|hizmet alimi|nakliye|kaldirma|tasima hizmet|dogrudan temin/;
  const exclude = /satilik|satis ihalesi|personel alimi|operator araniyor|hizmet veriyoruz|kiraya veriyoruz|iptal|sonuclandi/;
  for (const item of result.items) {
    if (checked >= 2) break;
    const title = fold6(String(item.title || ''));
    if (!equip.test(title) || !demand.test(title) || exclude.test(title)) continue;
    let target;
    try { target = new URL(item.url); } catch { continue; }
    if (target.protocol !== 'https:' || target.origin !== base.origin || target.username || target.password || target.port) continue;
    checked++;
    try {
      const page = await readPermittedHtmlPage(target.toString(), options.fetcher || fetch);
      if (new URL(page.url).origin !== base.origin) continue;
      const lines = sourceSentences(page.body).filter(s => {
        const t = fold6(s);
        return equip.test(t) && demand.test(t) && !exclude.test(t);
      }).slice(0, 5);
      if (!lines.length) continue;
      item.excerpt = (String(item.title || '') + '. ' + lines.join(' ')).slice(0, 1600);
      const authorDate = publisherPublication(page.body);
      if (authorDate) item.published_at = authorDate;
      enriched++;
    } catch {
      // A detail page failure must not interrupt other permitted notices.
    }
  }
  result.detail_checked = checked;
  result.detail_enriched = enriched;
  return result;
};

