async function tenderLoginGate(request,env) {
  const u=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{allow:'GET, HEAD'}});
  if(await currentMember(request,env)||await currentAdmin(request,env))return null;
  const login=new URL('/giris/','https://yukvinc.com.tr');
  login.searchParams.set('next',u.pathname+u.search);
  return new Response(null,{status:302,headers:{location:login.href,'cache-control':'private, no-store','x-robots-tag':'noindex',vary:'Cookie'}});
}
