      return new HTMLRewriter().on('head',{element(el){el.append('<link rel="stylesheet" href="/assets/mobile-listings214.css">',{html:true})}}).on('script[src]',{element(el){const src=el.getAttribute('src');if(path==='/hesabim/' && src && src.split('?')[0]==='/assets/account.js')el.setAttribute('src','/assets/account.js?v=214')}}).transform(response);
